function Item(props) {
    const coverValue = props.cover
    const nameValue = props.name
    const sizeValue = props.size
    const priceValue = props.price
    const comfortValue = props.comfort
    return (
        <div>
        <img className='item-cover' src={coverValue}
        alt={nameValue}/><br />
        {nameValue}<br />
        Taille : {sizeValue} <br />
        Confort : {comfortValue}
        </div>
    )
}

export default Item
